"""Verify compact results generated by the public CAS replication."""

from pathlib import Path
import runpy
import sys


project = Path(__file__).resolve().parent
verifier = project / "code" / "public_result_verifier.py"
arguments = list(sys.argv[1:])
if "--contract" not in arguments:
    arguments = ["--contract", str(project / "config" / "cas_public_result_contract.json"), *arguments]
if "--candidate-root" not in arguments:
    arguments = [*arguments, "--candidate-root", str(project)]
sys.argv = [str(verifier), *arguments]
runpy.run_path(str(verifier), run_name="__main__")
